# Input: PAC Bench affordance table; upstream card declares MIT. See README for scope.
"""Python standard library only. Run: python3 audit.py"""
import csv, hashlib, json
from pathlib import Path
p=Path(__file__).parent/'affordance_source.csv'
if not p.exists():
    import base64
    p.write_bytes(base64.b64decode(''))
rows=list(csv.DictReader(p.open(encoding='utf-8-sig',newline='')))
assert set(rows[0])=={'object','annotator','affordance1','affordance2','affordance3'}
counts={str(k):sum(sum(bool(r[f'affordance{j}'].strip()) for j in (1,2,3))==k for r in rows) for k in range(4)}
result={'rows':len(rows),'populated_slot_distribution':counts,'label_bearing_rows':len(rows)-counts['0'],'total_populated_slots':sum(int(k)*v for k,v in counts.items()),'zero_label_objects':[r['object'] for r in rows if not any(r[f'affordance{j}'].strip() for j in (1,2,3))],'source_sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
assert counts=={'0':1,'1':4,'2':50,'3':61}
print(json.dumps(result,indent=2))
(Path(__file__).parent/'audit_result.json').write_text(json.dumps(result,indent=2))

with (Path(__file__).parent/'category_audit.csv').open('w',newline='') as f:
    w=csv.writer(f);w.writerow(['row_id','object_category','recorded_affordance_slots','has_recorded_label','interpretation'])
    for i,r in enumerate(rows):
        k=sum(bool(r[f'affordance{j}'].strip()) for j in (1,2,3))
        w.writerow([i,r['object'],k,k>0,'recorded_label_available' if k else 'unknown_not_negative'])
